   106|export interface FailureClassification {
   107|  transient: boolean;
   108|  code: string;
   109|}
   110|
   111|const TRANSIENT_STATUS_CODES = new Set([429, 502, 503, 504, 408]);
   112|const PERMANENT_STATUS_CODES = new Set([400, 401, 403, 404, 422]);
   113|const TRANSIENT_MESSAGE_PATTERN = /timed?\s?out|timeout|connection reset|econnreset|econnrefused|socket hang ?up|network request failed|fetch failed|temporarily unavailable|service unavailable|rate.?limit|too many requests|aborted|etimedout|eai_again|overloaded/i;
   114|const PERMANENT_MESSAGE_PATTERN = /invalid input|invalid credentials|invalid api key|unauthorized|forbidden|not configured|environment variables are missing|payload too large|invalid json/i;
   115|
   116|/** Retry ONLY transient failures: 429/502/503/504, resets, timeouts (owner rule). */
   117|export function classifyFailureForRetry(input: { httpStatus?: number | null; message: string }): FailureClassification {
   118|  const status = input.httpStatus ?? null;
   119|  if (status !== null && PERMANENT_STATUS_CODES.has(status)) {
   120|    return { transient: false, code: `HTTP_${status}_PERMANENT` };
   121|  }
   122|  if (PERMANENT_MESSAGE_PATTERN.test(input.message)) {
   123|    return { transient: false, code: 'PERMANENT_INPUT_OR_AUTH' };
   124|  }
   125|  if (status !== null && TRANSIENT_STATUS_CODES.has(status)) {
   126|    return { transient: true, code: `HTTP_${status}_TRANSIENT` };
   127|  }
   128|  if (status !== null && status >= 500) {
   129|    return { transient: true, code: `HTTP_${status}_TRANSIENT` };
   130|  }
   131|  if (TRANSIENT_MESSAGE_PATTERN.test(input.message)) {
   132|    return { transient: true, code: 'NETWORK_OR_TIMEOUT_TRANSIENT' };
   133|  }
   134|  return { transient: false, code: 'UNKNOWN_PERMANENT' };
   135|}
   136|
   137|/** Exponential backoff with jitter. attempt is 1-based. */
   138|export function computeRetryDelayMs(
   139|  attempt: number,
   140|  baseMs: number = 2_000,
   141|  capMs: number = 60_000,
   142|  jitterRatio: number = 0.25,
   143|  random: () => number = Math.random,
   144|): number {
   145|  const exp = Math.min(capMs, baseMs * Math.pow(2, Math.max(0, attempt - 1)));
   146|  const jitter = exp * jitterRatio * (random() * 2 - 1);
   147|  return Math.max(500, Math.round(exp + jitter));
   148|}
   149|
   150|export interface FailureOutcome {
   151|  status: Extract<IVXOwnerAITaskStatus, 'RETRYING' | 'FAILED'>;
   152|  deadLetter: boolean;
   153|}
   154|
   155|/** Decide next status after a failed attempt. Exhausted transient retries → dead letter. */
   156|export function nextStatusAfterFailure(retryCount: number, maxRetries: number, transient: boolean): FailureOutcome {
   157|  if (!transient) return { status: 'FAILED', deadLetter: false };
   158|  if (retryCount >= maxRetries) return { status: 'FAILED', deadLetter: true };
   159|  return { status: 'RETRYING', deadLetter: false };
   160|}
